DROP POLICY "Samplers and store management can create sampling orders" ON public.quality_sampling_orders;
CREATE POLICY "Samplers and store management can create sampling orders" ON public.quality_sampling_orders FOR INSERT TO authenticated WITH CHECK ((lower(current_user_email()) = ANY (ARRAY['onesmusrubambura@greatpearlcoffee.com','sserunkumataufiq@greatpearlcoffee.com','tumwinealex@greatpearlcoffee.com','nuwagabagadaffi@greatpearlcoffee.com'])) OR can_manage_users() OR (EXISTS (SELECT 1 FROM employees e WHERE lower(e.email) = lower(current_user_email()) AND (('Store Management' = ANY (COALESCE(e.permissions, ARRAY[]::text[]))) OR (lower(COALESCE(e.role, '')) = ANY (ARRAY['store manager','store keeper','storekeeper']))))));